import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/products")
class ProductController {

    private final ProductRepository repository;

    ProductController(ProductRepository repository) {
        this.repository = repository;
    }

    // {id:[\d]+} rang buoc bien path chi khop gia tri so.
    @GetMapping("/{id:[\\d]+}")
    ResponseEntity<Product> findById(@PathVariable long id) {
        return repository.findById(id)
                .map(ResponseEntity::ok)
                .orElseGet(() -> ResponseEntity.notFound().build());
    }

    @GetMapping(produces = "application/json")
    ResponseEntity<java.util.List<Product>> search(
            @RequestParam(required = false) String category) {
        var results = category == null
                ? repository.findAll()
                : repository.findByCategory(category);
        return ResponseEntity.ok(results);
    }

    @PostMapping(consumes = "application/json")
    ResponseEntity<Product> create(@RequestBody Product product) {
        Product saved = repository.save(product);
        return ResponseEntity.status(201).body(saved);
    }
}

